let csrfToken = "";
// The kiosk keeps its own token: the AuthProvider clears the session token
// whenever /auth/me fails, which is exactly what happens on an unattended
// kiosk that never signs a person in.
let kioskCsrfToken = "";
export const setCSRF = (value: string) => {
  csrfToken = value;
};
export const setKioskCSRF = (value: string) => {
  kioskCsrfToken = value;
};

type APIErrorShape = { error?: { code?: string; message?: string } };
export class APIError extends Error {
  status: number;
  code: string;
  constructor(status: number, code: string, message: string) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers);
  if (init.body && !(init.body instanceof FormData))
    headers.set("Content-Type", "application/json");
  const token = csrfToken || kioskCsrfToken;
  if (token && !["GET", "HEAD"].includes(init.method ?? "GET"))
    headers.set("X-CSRF-Token", token);
  const response = await fetch(path, {
    ...init,
    headers,
    credentials: "same-origin",
  });
  if (!response.ok) {
    let data: APIErrorShape = {};
    try {
      data = await response.json();
    } catch {
      /* empty */
    }
    throw new APIError(
      response.status,
      data.error?.code ?? "request_failed",
      data.error?.message ?? `요청 실패 (${response.status})`,
    );
  }
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}

export function postJSON<T>(path: string, body: unknown) {
  return api<T>(path, { method: "POST", body: JSON.stringify(body) });
}
export function putJSON<T>(path: string, body: unknown) {
  return api<T>(path, { method: "PUT", body: JSON.stringify(body) });
}
export function patchJSON<T>(path: string, body: unknown) {
  return api<T>(path, { method: "PATCH", body: JSON.stringify(body) });
}
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { api, postJSON, setCSRF } from "./api";
import { clearSilentSsoState, markSignedOut } from "./silentSso";
import type { AuthConfig, User, VersionInfo } from "./types";

interface AuthState {
  user: User | null;
  phoneMasked: string;
  config: AuthConfig | null;
  version: VersionInfo | null;
  loading: boolean;
  login: (username: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  reload: () => Promise<void>;
}
const AuthContext = createContext<AuthState | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null),
    [phoneMasked, setPhoneMasked] = useState(""),
    [config, setConfig] = useState<AuthConfig | null>(null),
    [version, setVersion] = useState<VersionInfo | null>(null),
    [loading, setLoading] = useState(true);
  const reload = useCallback(async () => {
    try {
      const c = await api<AuthConfig>("/api/v1/auth/config");
      setConfig(c);
      setVersion(c.version);
      try {
        const me = await api<{
          user: User;
          phoneMasked?: string;
          csrfToken: string;
          version: VersionInfo;
        }>("/api/v1/auth/me");
        setUser(me.user);
        setPhoneMasked(me.phoneMasked ?? "");
        setVersion(me.version);
        setCSRF(me.csrfToken);
        // A live session lifts the silent-SSO suppression left by a sign-out.
        clearSilentSsoState();
      } catch {
        setUser(null);
        setCSRF("");
      }
    } finally {
      setLoading(false);
    }
  }, []);
  useEffect(() => {
    void reload();
  }, [reload]);
  const login = useCallback(
    async (username: string, password: string) => {
      await postJSON<User>("/api/v1/auth/login", { username, password });
      await reload();
    },
    [reload],
  );
  const logout = useCallback(async () => {
    // Recorded before the session goes away: signing the user straight back in
    // silently would make the sign-out look broken.
    markSignedOut();
    try {
      await api<void>("/api/v1/auth/logout", { method: "POST" });
    } finally {
      setUser(null);
      setCSRF("");
    }
  }, []);
  const value = useMemo(
    () => ({ user, phoneMasked, config, version, loading, login, logout, reload }),
    [user, phoneMasked, config, version, loading, login, logout, reload],
  );
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}
export function useAuth() {
  const value = useContext(AuthContext);
  if (!value) throw new Error("AuthProvider missing");
  return value;
}
