func (s *Server) checkIn(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Token   string `json:"token"`
		LobbyID string `json:"lobbyId"`
		Method  string `json:"method"`
		BadgeNo string `json:"badgeNo"`
	}
